SELECT
FROM resource r LEFT JOIN user u ON r.upload_user_id = u.id LEFT JOIN category c ON r.category_id = c.id WHERE r.upload_user_id = #{userId}
AND r.status = #{status}
ORDER BY r.create_time DESC

SELECT DISTINCT r.title FROM resource r WHERE r.status = 1
AND r.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY r.view_count DESC LIMIT #{limit}
